CREATE DATABASE IF NOT EXISTS rblx08 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rblx08;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(20) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,blurb TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen DATETIME NULL,tickets INT UNSIGNED NOT NULL DEFAULT 1000,robux INT UNSIGNED NOT NULL DEFAULT 0,role ENUM('user','moderator','admin') NOT NULL DEFAULT 'user',account_status ENUM('active','suspended','banned') NOT NULL DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS games(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,creator_id BIGINT UNSIGNED NULL,title VARCHAR(120) NOT NULL,description TEXT NULL,visits BIGINT UNSIGNED NOT NULL DEFAULT 0,status ENUM('active','hidden','removed') NOT NULL DEFAULT 'active',launch_url VARCHAR(500) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(creator_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS catalog_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,type ENUM('hat','shirt','pants','tshirt','face','head','other') NOT NULL DEFAULT 'other',description TEXT NULL,price INT UNSIGNED NOT NULL DEFAULT 0,creator_id BIGINT UNSIGNED NULL,stock INT UNSIGNED NULL DEFAULT NULL,sold_count BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_inventory(user_id,item_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES catalog_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS forum_topics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(120) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS forum_replies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES forum_topics(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS friendships(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 requester_id BIGINT UNSIGNED NOT NULL,
 addressee_id BIGINT UNSIGNED NOT NULL,
 status ENUM('pending','accepted','declined') NOT NULL DEFAULT 'pending',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uq_friendship(requester_id,addressee_id),
 FOREIGN KEY(requester_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY(addressee_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS private_messages(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 sender_id BIGINT UNSIGNED NOT NULL,
 recipient_id BIGINT UNSIGNED NOT NULL,
 subject VARCHAR(120) NOT NULL,
 body TEXT NOT NULL,
 is_read TINYINT(1) NOT NULL DEFAULT 0,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY(recipient_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS currency_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,currency ENUM('tickets','robux') NOT NULL,amount INT NOT NULL,reason VARCHAR(160) NOT NULL,reference_type VARCHAR(32) NULL,reference_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_currency_user(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS moderation_reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reporter_id BIGINT UNSIGNED NOT NULL,target_type ENUM('user','game','item','forum_topic','forum_reply') NOT NULL,target_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(1000) NOT NULL,status ENUM('pending','resolved','dismissed') NOT NULL DEFAULT 'pending',reviewed_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,KEY idx_reports_status(status,created_at),FOREIGN KEY(reporter_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS moderation_actions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,moderator_id BIGINT UNSIGNED NOT NULL,target_user_id BIGINT UNSIGNED NULL,action VARCHAR(40) NOT NULL,note VARCHAR(500) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(moderator_id) REFERENCES users(id),FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
